INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0001', 'kakao_philosophy', '문학', '국어농장주/조창훈', '[질문] 2024년도 홧팅!: 걍 흔들리지 말고 현재에 충실할 수 밖에 ~~~\n[조쌤] [속보]이규민 평가원장 사임 "6월 모평 책임…수험생·학부모에 죄송"\n출처 : 뉴시스 | 네이버 뉴스\n[반응] 티비 "못" 보는 무지: 어쩌자고ㅠㅠ', '2023-06-19 16:32:00');
INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0002', 'kakao_philosophy', '문학', '국어농장주/조창훈', '[질문] 국어잘하자: 아이고\n[질문] 콘이 웃긴 무지79: 헐 ㅠㅠ\n[질문] 운석의 여정: 6모가 어려웠었나여?\n[질문] 운석의 여정: 아닌에\n[조쌤] 오전에 보이스룸에서 마지막에... 말씀을 드렸듯....\n[조쌤] 평가원장님 포함 평가원 직원분들의 자괴감이 몹시 클 것 같습니다\n[반응] 열심히 일하는 네오라네오: 앗, 읽고 있었는뎅!\n[반응] 열심히 일하는 네오라네오: 틀린말씀 하나도 없던데요!', '2023-06-19 17:01:00');
INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0003', 'kakao_philosophy', '독해', '국어농장주/조창훈', '[조쌤] 입시 전문가나 타 과목 선생님들은\n난이도에 대한 걱정들을 하시지만...\n전 난이도는 사실 크게 상관 없다고 생각합니다\n처음에 난이도 얘긴 줄 알고 쉽게 나오든 어렵게 나오든 흔들릴 필요 없다는 주제로 보이스룸을 하려 했다가\n어제 저녁 기사들을 보고...\n엉뚱하게 비문학... 출제를 걸고 넘어진 것을 확인한 후로는\n평가원에서 도대체 국어(타과목은 아예 예를 들지 않았지요. 국어 비문학의 예만 들었어요ㅠ) 영역에서 특히 비문학을 어떻게 출제하라는 건지 도저히 감이 안 왔고....\n국장 경질 소식에 교육과정과의 연결성을 대통령께 설명하는 것이 먹히지 않겠구나... 싶으니까... 평가원에서 아무것도 할 수 없는 상황이라는 걸 느꼈습니다\n심지어 평가원을 사교육과 이권 카르텔이라 몰고 가는 모습까지 보니... 제가 평가원 관계자여도 어마어마한 자괴감이 들 것 같았습니다\n오전에 언급했듯 수능 국어(특히 비문학)는 수능의 원 취지에 잘 부합하는 좋은 문제들입니다. 많은 비용과 연구를 거\n[조쌤] 쓰다가 엔터가 쳐저서 글이 완성되기 전 올라가버렸어요\n[반응] 운석의 여정: 오늘은 술을 까야할것같습니다. 나 원래 술안먹는 사람인데\n[반응] 운석의 여정: .............. 술먹고 행패부리고 싶습니다 ......', '2023-06-19 17:13:00');
INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0004', 'kakao_program', '문학', '국어농장주/조창훈', '[질문] 이노센세: 그런데 저 방을 들어가면 어떻게 되나여?\n[질문] 국어를 생각하는 라이언: 가리는 중이셨군요 ㅎ 많이도 올렸네..\n[질문] 디셈버글로리: 알려주셔서 감사합니다. 타이밍도 참 일부러 맞춰서 한거처럼 ㅜㅜ\n[질문] ㄱ4굿쌤수학전문학원♡: 제가 덩치가 쬐금 왜소하여^^\n[조쌤] 오늘 설명회 참석해주신 모든 분께 감사드립니다^^\n이제 정리 마무리하고 퇴근합니다\n늘 노력 발전하는 국어농장이 되겠습니다\n[반응] Ss: 독박 육아에 워킹맘이라 직접 가보진 못했지만..너무 고생 많으셨어요~~\n[반응] 🫧: 수고하셨어요~~😊\n[반응] 엄지척: 오늘 너무 좋았습니다~\n조창훈 원장님 뵌것도 👍\n오전 보이스룸 듣질 못해서 아쉬웠는데 그 맘이 싹~ 워킹맘을 위한 설명회 너무 감사합니다\n수고하셨습니다', '2023-06-19 21:35:00');
INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0005', 'kakao_philosophy', '독해', '국어농장주/조창훈', '[질문] 하트뿅뿅 라이언: 좋은 아침입니다.\n[질문] 채니: 좋은아침입니다.^^\n[조쌤] 굿모닝입니다\n[질문] 요놈의 감홍시: 행복한 하루되세요^^\n[조쌤] 사진 2장\n[조쌤] 어제 설명회 참석해주신 모든 분들께 감사드립니다\n모두들 즐거운 하루 보내십시오\n[조쌤] 드디어 어제 말씀드린... 내용들이 기사화가 되기 시작하는군요... 교과과정 내 출제 얘기를 하면서 국어 비문학을 언급한 것 킬러 문제 얘기르루하면서 국어를 걸고 넘어진 것이 왜 말도 안 되는 일인지 제가 말씀드린 내용과 동일한 이야기를 기사 내에서 다른 분들도 하시네요\n[조쌤] 불필요한 논란임이 분명합니다... 수능 5개월 남기고 아이들이 무슨 죕니까 ㅠ 당장 기출 분석을 해야 하는지 수특 독서를 파야 하는지... 독서 교과서들을 출판사별로 구해야 하는지\n9평 전까지 누구도 알 수 없게 돼버렸으니 말입니다....\n재수생들은 반 년 간 국어 공부한 게\n의미가 있는지 새로이 새 방법으로 해야 하는지 당장 혼란스러울 테구요...\n[반응] 건강하자♥️초6: 안녕하세요^^\n[조쌤] 반갑습니다^^\n[반응] 권투하는 무지: 굿모닝 입니다!', '2023-06-20 07:19:00');
