INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0031', 'kakao_philosophy', '문학', '국어농장주/조창훈', '[조쌤] 30대가 지나면 후회할 일이라고 꼭.... 전해주세요\n[조쌤] 재수생 수업을 마치고 휴식중인데... 부흥고3 국어 시험지가 왔네요\n[조쌤] 이제 시험기간임이 실감 납니다\n[조쌤] 이번 주에 시험지 사진을 올려주시면 다음 주 보이스룸 때 해당 학교 시험지에 대해 어떻게 분석하는지 보이스룸에서 알려드리겠습니다\n[조쌤] 파일: [교육부 06-26(월) 브리핑시(15시) 보도자료] [별첨 2] 최근 3년간 수능 및 ’23.6월 모의평가 소위 ‘킬러문항’ 사례.PDF\n[조쌤] 킬러인 이유까지 달린 버전이랍니다\n[반응] 운석의 여정: (샘 전.. 쌩쌩해요.. 쏘리...', '2023-06-26 14:16:00');
