INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0156', 'kakao_program', '프로그램안내', '국어농장주/조창훈', '[질문] 구거남우: 사진 3장\n[질문] 구거남우: 작년에 했던 청산별곡의 느낀점 보면서 지금도 그렇게 느껴지는지 물어보니 이번에는 마음이 아픈 사람이 쓴 거 같다고 하네요~\n다음에 만날 때의 청산별곡은 또 어떤 느낌일지 궁금합니다^^\n모두 편안한 밤 보내세요😊\n[질문] 왕초보 국어 학부모: 딸내미가 이쁘게 잘적었는데~\n카메라가 깨져 흐릿하게 나와서 아쉽네요~~^^\n[조쌤] ㅎㅎㅎ 국어농장 소감까지 너무너무 고맙다고 전해주셔요^^\n[반응] 왕초보 국어 학부모: 네~^^\n[조쌤] 굿모닝입니다^^', '2023-08-04 22:52:00');
