INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0444', 'kakao_advice', '초등학습', '국어농장주/조창훈', '[질문] 믿음맘: 노래 감상중\n너무 감사합니다.\n[질문] 반지의제왕: 어머나..ㅠㅠ\n들으니 왜이리 센치해지는거죠ㅠㅠ\n[조쌤] 오늘 휴무라 아들 데리러 왔습니다^^\n[조쌤] 모두들 10월 마지막 오후 즐겁게 보내셔요!!!\n[질문] 카사블랑카: 옛 노래 좋아하는 초등 아들이 옆에서 감동받고 있어요. 계속 틀어 달라며♡\n[조쌤] ㅎㅎㅎㅎ 신기하네여^^ 초등이 좋아할 만한 노래가 아닌데;;\n[반응] 카사블랑카: 이 아이가 부활도 좋아하고 퀸도 좋아하고ㅋㅋ\n[반응] 카사블랑카: 나훈아 할부지도 좋아하고 머 그렇네여 ㅎㅎ\n[반응] 믿음맘: 세상에... 크게 될 아이 같습니다. 남다른 감성이네요. 부활, 퀸이라니요.. 대박~', '2023-10-31 14:54:00');
