INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0582', 'kakao_advice', NULL, '국어농장주/조창훈', '[조쌤] 넵^^\n[조쌤] 근데 기저귀 도서관엔 한옥식 룸이 있어서\n[조쌤] 함께 작업하기가 너무 좋더라구요\n[조쌤] 거기에 반해서 매주 갈 생각이었답니다^^\n[질문] j사랑: 오늘 같은 날 방바닥 뜨신데 몸 푹 지지고 싶네요.^^;;\n[조쌤] 네 아들 우산만 챙겨줬으면 뜨끈뜨끈한 곳에 앉아서 작업했을 텐데\n[조쌤] 아쉬워하며 남천까지 왔네요\n[반응] 가보자! 우리 중딩이: 날씨 좋으면 도서관 맞은편 공원산책도 좋습니다~~ 또 오실 기회가 있다면 근린공원 산책도 추천합니다. 원장님~~^^\n[조쌤] 넵!!', '2023-12-14 13:23:00');
