INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0622', 'kakao_program', '문학', '국어농장주/조창훈', '[질문] j사랑: 감사합니다\n[질문] 반지의제왕: 그림도 이뻐요^^\n제가 가장 좋아하는 영화가 <미녀와야수>라서ㅎ\n답글달아봅니다.\nBeauty is found within.\n[조쌤] 안녕하세요? 국어농장입니다.\n자녀분과 함께 오시면\n어머님은 설명회와 간담회를\n자녀분은 체험 학습을!\n* 대상 :  초등 어머님과 초등학생\n* 일시 : 24.1.3 (수) 오전 11시\n* 위치 : 센텀 서울어학원\n(센텀 2로 10, 센텀메디컬 빌딩 2층)\n신청 완료시 확정 문자 및 카톡을 보내드립니다.\n↓↓아래의 링크로 신청바랍니다!\nhttps://forms.gle/D4YHipWLjoYka24j9\n문의 051-702-7412 (언어의창) 010-8950-0655 (문자, 카톡전용)\n[조쌤] 굿모닝입니다\n[조쌤] Hi님이 나가셨다는 표현은 조금 역설적 표현 같네여^^;;\n[조쌤] 농장장 여러분들 모두 건강한 하루 보내셔요!\n[반응] 국어잘하자: 좋은아침입니다.\n오늘도 힘찬하루~화이팅입니다.\n[반응] 구거남우: 굿모닝입니다^^\n오늘도 좋은 하루 보내세요👍', '2023-12-27 22:08:00');
INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0623', 'kakao_advice', '문학', '국어농장주/조창훈', '[조쌤] 농장방 여러분들입니다\n(오타 정정)\n[조쌤] 너무 어두워서\n이게 맞나 하고 폰을 보니\n일출 시간이 7시 31분이네요\n[조쌤] 늦잠 자기 딱 좋은 때로군요;;\n[반응] 요놈의 감홍시: 별 생각 없다가 시간으로 보니 해가 많이 늦게 뜬다는 기분이 드네요;;\n좋은 아침입니다^^', '2023-12-28 07:04:00');
