INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0809', 'kakao_program', NULL, '국어농장주/조창훈', '[질문] 보리보리: 감사합니다\n행복한 명절 되세요~\n[조쌤] 굿모닝입니다\n[질문] 감사만땅: 새해 복 많이 받으세요~\n[조쌤] 아... 새해 인사 이미지를 챗GPT로 만들려고 했는데 이런 게 나와버렸...네여\n[반응] 감사만땅: 퀴즈게임하고는 타이밍이 영~ 안맞네요ㅋㅋㅋ\n다음기회에~~\n[반응] 감사만땅: 원장님은 복 더더 많이 받으세요~^^\n항상  감사합니다^^\n[조쌤] 어쿠 저도 감사합니다^^ 새해 복 많이 받으셔요!!', '2024-02-10 06:28:00');
