INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_0969', 'kakao_advice', NULL, '국어농장주/조창훈', '[조쌤] 아... 아들이 장가를 안 가고\n[조쌤] 어머니에게 선물을 주려 하니까\n[질문] 네오옹: 아내가 없지만 있었으면 좋겟어서\n[질문] 네오옹: 그런건가요??\n[질문] 네오옹: 어머니가 그냥 그렇게말한건가요..?\n[조쌤] 그런 선물 엄마(나)에게 하지 말고 얼른 장가 가서 아내에게나 하거라\n[반응] 네오옹: 아 그래서 그렇군야\n[조쌤] 라는 뜻으로 한 말입니다\n[반응] 네오옹: 감사합니다!!!!!', '2024-03-21 21:00:00');
