INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_1283', 'kakao_program', '프로그램안내', '국어농장주/조창훈', '[조쌤] 국어농장 온라인 학습과 교재 학습을 병행하는 거랍니다\n[조쌤] 파일: 국어농장 학습 안내 책자(설명회용)_20240311_221248_0000.pdf\n[반응] 4 봄아: 홈피 들어왔는데 이용안내에 없어서요..\n홈페이지는 개인회원만 있는거 같던데요..\n[조쌤] 위 안내 책자를 참고해주셔요^^\n[반응] 4 봄아: 지금 읽어보겠습니다.', '2024-09-28 22:19:00');
