INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_1876', 'kakao_program', '문학', '국어농장주/조창훈', '[조쌤] 앗 네네\n[질문] 울고있는 어피치: (와..늘님 오심)\n[조쌤] 굿모닝입니다\n[질문] 보노보노: 좋은아침입니다😄\n[조쌤] 파일: 국어농장]자가진단시중교재추천.html\n[조쌤] 클릭하시면 간단한 자가 진단 및 시중 교재 추천이 이뤄집니다\n실행이 안 되시는 분들은 저장하셔서 크롬으로 열기 해주시면 되셔요\n[조쌤] 제가 만들었지만... 정말 잘 만든 거 같습니다 강추윕니다!\n[조쌤] 이상한 오타가...\n강추입니다\n[반응] 개춘식: 덥지만 화이팅하세요들~', '2025-07-22 07:41:00');
