INSERT INTO ai_chat_references (id, source, topic, speaker, content, spoken_at) VALUES ('ref_kakao_1948', 'kakao_philosophy', NULL, '국어농장주/조창훈', '[질문] 박스에 들어간 춘식이: 항상 감사합니다\n[조쌤] 굿모닝입니다\n[조쌤] 며칠 전에 수업하는데\n[조쌤] 아들이 다급하게 연락 와서 집에 바퀴벌레가 날아다닌다.. 그래서 집 밖으로 나왔다.. 하길래\n[조쌤] 에프킬러 있으니 잡거라... 라고 했는데\n[조쌤] 한 마리 잡는 데 한 통을 다 뿌렸더라구요\n[조쌤] 바닥에 눈처럼 약이 하얗게 쌓이도록 뿌려서 잡는 걸... 영상으로 찍어서 저에게 보냈길래', '2025-08-19 11:03:00');
